function renumberCards() {
  const cards = $('questions-container').querySelectorAll('.q-card');
  cards.forEach((c, idx) => {
    const lbl = c.querySelector('.q-num-label');
    if (lbl) lbl.textContent = 'Question ' + (idx + 1);
  });
}

$('add-q-btn').onclick = () => {
  const container = $('questions-container');
  const count = container.querySelectorAll('.q-card').length + 1;
  const newCard = createQuestionCard({}, count);
  container.appendChild(newCard);
  newCard.scrollIntoView({ behavior: 'smooth' });
};

function populateQuizData(quiz) {
  $('qtitle').value = quiz.title || '';
  $('qdesc').value = quiz.description || '';
  if (quiz.settings) {
    settingsState = { ...settingsState, ...quiz.settings };
  }
  syncOptionsUI();
  const container = $('questions-container');
  container.innerHTML = '';
  (quiz.questions || []).forEach((q, idx) => {
    container.appendChild(createQuestionCard(q, idx + 1));
  });
  if ((quiz.questions || []).length === 0) {
    container.appendChild(createQuestionCard({}, 1));
  }
}

function loadTeacherQuiz() {
  populateQuizData(defaultQuiz);
  if (db) {
    db.collection("quizzes").doc(quizId).get().then(doc => {
      if (doc.exists) {
        populateQuizData(doc.data());
        $('status-msg').textContent = 'Loaded active quiz Locally.';
        $('status-msg').style.color = 'var(--ok)';
      }
    }).catch(() => {});
  }
}
loadTeacherQuiz();

$('save-btn').onclick = () => {
  const title = $('qtitle').value.trim();
  const desc = $('qdesc').value.trim();
  if (!title) {
    $('status-msg').textContent = 'Please enter a quiz title.';
    $('status-msg').style.color = 'var(--bad)';
    return;
  }
  settingsState.tabViolationPenalty = parseInt($('pen-val').value, 10) || 0;
  settingsState.timePerQuestion = parseInt($('time-val').value, 10) || 20;

  const cards = $('questions-container').querySelectorAll('.q-card');
  const questions = [];
  cards.forEach(c => {
    const q = c.querySelector('.q-text').value.trim();
    const correct = c.querySelector('.q-corr').value.trim();
    const w1 = c.querySelector('.q-w1').value.trim();
    const w2 = c.querySelector('.q-w2').value.trim();
    const w3 = c.querySelector('.q-w3').value.trim();
    const exp = c.querySelector('.q-exp').value.trim();
    if (q || correct) {
      questions.push({
        q,
        correct,
        wrongs: [w1, w2, w3].filter(Boolean),
        explanation: exp
      });
    }
  });

  if (questions.length === 0) {
    $('status-msg').textContent = 'Please add at least one question.';
    $('status-msg').style.color = 'var(--bad)';
    return;
  }

  $('status-msg').textContent = 'Saving...';
  $('status-msg').style.color = 'var(--mu)';
  if (db) {
    db.collection("quizzes").doc(quizId).set({
      title,
      description: desc,
      settings: settingsState,
      questions,
      updatedAt: Date.now()
    }).then(() => {
      $('status-msg').textContent = 'Saved Successfully to Student Quiz File! Quiz is live.';
      $('status-msg').style.color = 'var(--ok)';
    }).catch(err => {
      if (err.code === 'permission-denied' || String(err).includes('permission')) {
        $('status-msg').textContent = 'Security rules currently block quiz overwrite (allow write: if false). Use Download QUIZ Json to download index.html.';
      } else {
        $('status-msg').textContent = 'Error saving: ' + err.message;
      }
      $('status-msg').style.color = 'var(--bad)';
    });
  } else {
    $('status-msg').textContent = 'Database is not initialized.';
    $('status-msg').style.color = 'var(--bad)';
  }
};

$('dl-quiz-btn').onclick = async () => {
  try {
    const res = await fetch('index.html');
    if (res.ok) {
      const html = await res.text();
      const blob = new Blob([html], { type: 'text/html' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = 'index.html';
      a.click();
      return;
    }
  } catch (e) { }
  const a = document.createElement('a');
  a.href = 'index.html';
  a.download = 'index.html';
  a.click();
};
